int group_sort(char *str)
{
    char last_capital, last_small, last_digit;
    int i;
    last_capital = last_small = last_digit = '\0';
    for (i = 0; str[i] != '\0'; i++)
        if (isupper(str[i]))
            if (str[i] < last_capital)
                return 0;
            else
                last_capital = str[i];
        else
            if (islower(str[i]))
                if (str[i] < last_small)
                    return 0;
                else
                    last_small = str[i];
            else
                if (isdigit(str[i]))
                    if (str[i] < last_digit)
                        return 0;
                    else
                        last_digit = str[i];
    return 1;
}
```

